import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Parse scene position with defaults
  const scenePos = config.scenePosition || {};
  const position = [scenePos.x ?? 0, scenePos.y ?? 0, scenePos.z ?? 0];
  const rotation = scenePos.rotationXYZ ?? [0, 0, 0];
  const scale = scenePos.scaleXYZ ?? [1, 1, 1];

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Create material with TSL
  const material = new MeshBasicNodeMaterial();

  // Load texture if provided
  let loadedTexture = null;
  if (config.imageUrl) {
    loadedTexture = ctx.textureLoader.load(config.imageUrl);
    loadedTexture.colorSpace = THREE.SRGBColorSpace;
    material.map = loadedTexture;
  }

  // Create and configure mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.fromArray(position);
  mesh.rotation.order = 'XYZ';
  mesh.rotation.fromArray(rotation);
  mesh.scale.fromArray(scale);

  group.add(mesh);

  // Add text content via MSDF
  if (Array.isArray(config.textContent) && config.textContent.length > 0) {
    for (const textItem of config.textContent) {
      if (textItem && textItem.text) {
        try {
          const textMesh = ctx.fontAtlas.createTextMesh({
            text: textItem.text,
            fontSize: textItem.fontSize || 0.2,
            color: textItem.color || 0xe8ecf2,
            anchor: textItem.anchor || [0.5, 0.5]
          });

          if (textMesh) {
            textMesh.position.z = 0.01;
            group.add(textMesh);
          }
        } catch (e) {
          // Silently skip if text rendering fails
        }
      }
    }
  }

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primRef of config.cinematicPrimitives) {
      if (primRef.name && ctx.primitives[primRef.name]) {
        ctx.primitives[primRef.name](group, primRef.params || {});
      }
    }
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // Setup event handlers
  group.userData.handlers = {};

  return group;
}
